"""Concrete bilingual explanations tied to the exact statements in the examples."""
import ast


def pair(pl, en):
    return {'pl': pl, 'en': en}


EXACT = {}


def note(line, pl, en):
    EXACT[line] = pair(pl, en)


note('app = web.Application()', 'Tworzymy aplikację aiohttp. Przechowa router i stan; ta linia jeszcze nie otwiera portu ani nie obsługuje żądania.', 'Create the aiohttp application, which holds routing and state. This line does not open a port or handle a request yet.')
note('def create_app(factory):', 'Definiujemy zwykłą funkcję budującą aplikację. Otrzymuje fabrykę sesji i zwróci skonfigurowany obiekt web.Application. Nie wykonuje operacji I/O, więc nie potrzebuje async.', 'Define an ordinary application factory. It receives the session factory and returns a configured web.Application. It performs no I/O and needs no async.')
note('app = create_app(factory)', 'Wywołujemy funkcję tworzącą aplikację: zapisze fabrykę sesji i wywoła setup_routes z osobnego modułu. Zwrócony obiekt trafia do app; serwer uruchomi dopiero demo.', 'Call the application factory: it stores the session factory and invokes setup_routes from a separate module. The returned object becomes app; demo starts the server later.')
note('return app', 'Zwracamy skonfigurowaną aplikację do main. Zarejestrowane trasy są gotowe, lecz port jeszcze nie nasłuchuje. return kończy create_app.', 'Return the configured application to main. Routes are registered, but no port is listening yet. return ends create_app.')
note('app[SESSION] = factory', 'Pod kluczem SESSION zapisujemy fabrykę sesji, nie jedną wspólną sesję. Każdy handler utworzy własną AsyncSession, więc równoległe żądania nie dzielą transakcji.', 'Store the session factory under SESSION, rather than a shared session. Each handler creates its own AsyncSession, so concurrent requests do not share transactions.')
note('async with database(Base) as factory:', 'Wchodzimy do pomocnika database z api_support.py. Tworzy osobny schemat w bazie lesson32, tabele z Base.metadata i fabrykę AsyncSession. Przy wyjściu usuwa tylko schemat tego pokazu i zamyka silniki. To przygotowanie demonstracji, a nie kod handlera.', 'Enter database from api_support.py. It creates a separate schema in lesson32, tables from Base.metadata and an AsyncSession factory. On exit it removes only this demo schema and closes the engines. This is demo setup, not handler code.')
note('async with request.app[SESSION]() as session:', 'request.app to aplikacja, która odebrała żądanie. [SESSION] pobiera fabrykę; () tworzy nową sesję. async with dopilnuje jej zamknięcia i zwrotu połączenia. Samo wejście nie oznacza zapisu danych.', 'request.app is the receiving application. [SESSION] retrieves the factory; () creates a new session. async with closes it and returns its connection. Entering alone does not save data.')
note('async with session.begin():', 'Rozpoczynamy zakres transakcji. Prawidłowe wyjście zatwierdzi zmiany przez COMMIT; wyjątek opuszczający blok uruchomi ROLLBACK. Wcięcie wskazuje, które instrukcje należą do tej transakcji.', 'Start a transaction scope. Normal exit commits changes; an exception escaping the block triggers ROLLBACK. Indentation identifies the statements belonging to this transaction.')
note('async with factory.begin() as session:', 'Fabryka tworzy sesję i rozpoczyna transakcję do przygotowania danych. Przy poprawnym wyjściu zapisze rekordy, a następnie zamknie sesję; wyjątek spowoduje rollback.', 'The factory creates a session and starts a transaction for seed data. Successful exit commits records and closes the session; an exception rolls back.')
note('await session.flush()', 'flush wysyła oczekujące INSERT/UPDATE do PostgreSQL i czeka na odpowiedź. Nowy obiekt otrzymuje ID. To jeszcze nie COMMIT: późniejszy wyjątek nadal może wycofać tę zmianę.', 'flush sends pending INSERT/UPDATE statements to PostgreSQL and awaits completion. A new object receives its ID. This is not COMMIT: a later exception can still roll back the change.')
note('session.add(product)', 'Dołączamy obiekt product do sesji. To zwykła metoda bez await: rejestruje plan zapisu w pamięci. INSERT zostanie wykonany podczas flush lub zatwierdzania.', 'Attach product to the session. This ordinary method needs no await: it registers pending work in memory. INSERT happens at flush or commit.')
note('session.add(user)', 'Rejestrujemy nowego użytkownika w sesji. Jeszcze nie znamy ID z bazy; uzyskamy je po flush.', 'Register the new user with the session. Its database-generated ID becomes available after flush.')
note('result = product.to_dict()', 'Metoda to_dict kopiuje id, name i price do zwykłego słownika result. Po flush ID już istnieje. Słownik nie zależy od otwartej sesji.', 'to_dict copies id, name and price into an ordinary result dictionary. After flush the ID is available. The dictionary does not depend on an open session.')
note('product = Product(name=data["name"], price=data["price"])', 'Tworzymy obiekt ORM z wartości ze słownika JSON, np. Notebook i 1299 groszy. To na razie obiekt Pythona, bez rekordu w bazie.', 'Construct an ORM object from JSON values, for example Notebook and 1299 cents. It is initially a Python object, without a database record.')
note('product_id = positive_id(request.match_info["id"])', 'Router zapisał fragment {id} jako tekst, np. "1". positive_id zamienia go na dodatni int i odrzuca błędne dane statusem 400. product_id będzie użyty w zapytaniu do bazy.', 'The router captured {id} as text, such as "1". positive_id converts it into a positive int and rejects invalid input with 400. product_id is used in the database query.')
note('product = await session.get(Product, product_id)', 'Pobieramy Product po kluczu głównym. await czeka na odczyt bazy, dając pętli możliwość obsługi innych zadań. Wynik to obiekt Product albo None.', 'Retrieve Product by primary key. await waits for database I/O while allowing the loop to handle other tasks. The result is a Product object or None.')
note('statement = select(Product).order_by(Product.id)', 'Budujemy opis SELECT produktów w kolejności ID. Baza jeszcze nie dostała zapytania. order_by zapewnia przewidywalną kolejność rekordów.', 'Build a SELECT description for products ordered by ID. The database has not received it yet. order_by makes record order predictable.')
note('result = await session.execute(statement)', 'Dopiero execute wysyła przygotowane statement do bazy. await odbiera wynik. result opakowuje wiersze; nie jest jeszcze listą słowników JSON.', 'execute now sends the prepared statement to the database. await receives its result. result wraps rows; it is not a list of JSON dictionaries yet.')
note('products = result.scalars().all()', 'Dla select(Product) scalars wyciąga obiekt Product z każdego wiersza, a all zbiera obiekty do listy. Wynik jest już pobrany, więc tutaj nie ma await.', 'For select(Product), scalars extracts each Product object and all collects them into a list. Data has already been retrieved, so no await is needed here.')
note('return {"id": self.id, "name": self.name, "price": self.price}', 'self oznacza bieżący produkt. Tworzymy słownik z trzema wartościami, które można zapisać jako JSON. return oddaje go wywołującej funkcji i kończy metodę.', 'self is the current product. Create a dictionary containing three JSON-compatible values. return sends it to the caller and ends the method.')
note('name = request.match_info["name"]', 'Odczytujemy nazwę z fragmentu URL {name}. Dla /witaj/Anna zmienna name otrzyma tekst "Anna". To parametr ścieżki, nie query string ani JSON.', 'Read the name captured by the URL placeholder {name}. /witaj/Anna gives name the string "Anna". This is a path parameter, not a query string or JSON body.')
note('query = request.query.get("q")', 'Z query string odczytujemy q. Dla ?q=python dostaniemy "python"; bez q metoda get zwróci None, zamiast zgłosić KeyError. ?q= daje pusty tekst.', 'Read q from the query string. ?q=python returns "python"; absent q returns None rather than KeyError. ?q= returns an empty string.')
note('now = datetime.now().isoformat()', 'now pobiera lokalny czas komputera, a isoformat zmienia go na tekst JSON, np. 2026-10-22T12:34:56. Ten wariant nie zawiera informacji o strefie czasowej.', 'now gets local computer time and isoformat converts it into JSON-compatible text, such as 2026-10-22T12:34:56. This variant has no timezone information.')
note('data = await request.json()', 'Czekamy na ciało żądania i parsujemy JSON do obiektu Pythona. Przykład {"message":"Python"} staje się słownikiem. Niepoprawny JSON przechodzi do except.', 'Wait for the request body and parse JSON into a Python object. {"message":"Python"} becomes a dictionary. Invalid JSON transfers control to except.')
note('data = await object_json(request)', 'Pomocnik czyta JSON i sprawdza, czy wynikiem jest słownik. Zwraca go do data. Niepoprawny JSON lub lista zamiast obiektu kończą żądanie statusem 400.', 'The helper reads JSON and checks that the result is a dictionary. It returns that dictionary into data. Invalid JSON or an array instead of an object ends the request with 400.')
note('data = product_fields(await object_json(request))', 'Najpierw await object_json pobiera słownik z żądania. Potem product_fields sprawdza wymagane name i price: nazwę 1–100 znaków oraz nieujemną cenę w groszach typu int. Dopiero poprawny słownik trafia do data.', 'First await object_json reads a request dictionary. Then product_fields checks required name and price: a 1–100 character name and a nonnegative integer price in cents. Only a valid dictionary reaches data.')
note('data = product_fields(await object_json(request), partial=True)', 'Czytamy słownik i walidujemy częściową zmianę. partial=True pozwala przesłać samo name lub samo price. Pola nieobecne w JSON zachowają dotychczasowe wartości.', 'Read and validate a partial update dictionary. partial=True allows name alone or price alone. Fields absent from JSON retain their previous values.')
note('product.name = data["name"]', 'Zmieniamy atrybut obiektu śledzonego przez sesję. SQLAlchemy wykryje tę zmianę i przygotuje UPDATE podczas flush lub commit.', 'Change an attribute of the session-tracked object. SQLAlchemy detects it and prepares UPDATE at flush or commit.')
note('product.price = data["price"]', 'Przypisujemy nową cenę w groszach, np. 999. Nie mnożymy ani nie dzielimy jej przez 100; baza również przechowuje liczbę całkowitą.', 'Assign the new price in cents, for example 999. Do not multiply or divide by 100; the database stores an integer too.')
note('await session.delete(product)', 'Oznaczamy produkt do usunięcia. Metoda asynchroniczna może wymagać odczytów związanych z kaskadą. Sam DELETE zostanie wysłany przy flush/commit, a zapis zatwierdzi wyjście z begin.', 'Mark the product for deletion. This async method may need reads for cascades. DELETE is sent at flush/commit; exiting begin commits the operation.')
note('offset = (page - 1) * limit', 'Obliczamy liczbę pomijanych rekordów. Dla page=2 i limit=1 offset wynosi 1. Strona pierwsza pomija 0; numerujemy strony od 1.', 'Calculate the number of skipped records. page=2 and limit=1 gives offset=1. The first page skips 0; page numbering starts at 1.')
note('statement = select(Product).order_by(Product.id).offset(offset).limit(limit)', 'Budujemy SELECT ze stałą kolejnością ID, pominięciem offset rekordów i maksymalnie limit wynikami. Dla strony 2, limitu 1 otrzymamy drugi produkt. Nadal nie wykonujemy I/O.', 'Build SELECT ordered by ID, skipping offset records and returning at most limit results. Page 2 with limit 1 selects the second product. No I/O happens yet.')
note('statement = select(Product, User).join(User).where(Product.id == product_id)', 'SELECT pobiera pary Product i User. JOIN korzysta z ForeignKey products.user_id → users.id, a where ogranicza wynik do wskazanego produktu. To opis jednego zapytania, jeszcze bez wysyłania do bazy.', 'SELECT retrieves Product and User pairs. JOIN uses ForeignKey products.user_id → users.id, and where selects the requested product. This describes a single query without executing it yet.')
note('row = result.one_or_none()', 'Odbieramy jeden wiersz albo None. Ponieważ SELECT obejmuje dwa modele, wiersz zawiera parę obiektów, a nie sam produkt. Więcej niż jeden wiersz zgłosi wyjątek.', 'Retrieve one row or None. Since SELECT includes two models, the row holds a pair of objects, not just the product. More than one row raises an exception.')
note('product, user = row', 'Rozpakowujemy dwuelementowy wiersz: pierwszy obiekt trafia do product, drugi do user. Kolejność odpowiada select(Product, User).', 'Unpack the two-element row: the first object becomes product and the second user. The order matches select(Product, User).')
note('user = User(username="Anna")', 'Tworzymy użytkownika Anna w pamięci. Kolejne add i flush zapiszą go i pobiorą ID potrzebne jako klucz obcy produktu.', 'Construct user Anna in memory. The following add and flush insert it and retrieve the ID needed as the product foreign key.')
note('session.add(Product(name="Notebook", price=1299, user_id=user.id))', 'Przygotowujemy produkt Notebook za 1299 groszy. user.id znamy po flush użytkownika. user_id łączy produkt z jego twórcą; COMMIT nastąpi przy wyjściu z transakcji.', 'Prepare Notebook priced at 1299 cents. user.id is known after flushing the user. user_id links the product to its creator; exiting the transaction commits it.')
note('by_id = {account.id: account for account in accounts}', 'Tworzymy słownik przez comprehension: kluczem jest ID, wartością obiekt Account. Dzięki temu wybierzemy konto źródłowe i docelowe po ID, niezależnie od kolejności przesłanej w JSON.', 'Create a dictionary comprehension mapping ID to Account. This lets us select source and target by ID regardless of the order submitted in JSON.')
note('source = by_id[data["from_id"]]', 'Ze słownika kont pobieramy obiekt konta źródłowego. Przy from_id=1 to konto z początkowym saldem 1000 groszy.', 'Retrieve the source account from the mapping. With from_id=1, this is the account initially holding 1000 cents.')
note('target = by_id[data["to_id"]]', 'Pobieramy konto odbiorcy. Dla to_id=2 początkowe saldo wynosi 500 groszy. source i target są różnymi obiektami.', 'Retrieve the destination account. With to_id=2 its initial balance is 500 cents. source and target are distinct objects.')
note('source.balance -= data["amount"]', 'Odejmujemy kwotę od salda źródła w obiekcie ORM. Dla przelewu 100: 1000 → 900. Następny flush wyśle UPDATE, ale zmiana nadal należy do niezatwierdzonej transakcji.', 'Subtract the amount from the source ORM balance. A transfer of 100 changes 1000 → 900. The next flush sends UPDATE, but the change still belongs to an uncommitted transaction.')
note('target.balance += data["amount"]', 'Dodajemy tę samą kwotę odbiorcy: 500 → 600 dla przelewu 100. Obie zmiany zatwierdzą się razem. Suma sald pozostaje 1500.', 'Add the same amount to the target: 500 → 600 for a transfer of 100. Both changes commit together. Total balance remains 1500.')
note('statement = select(Account).where(Account.id.in_([data["from_id"], data["to_id"]])).order_by(Account.id).with_for_update()', 'Wybieramy oba konta i żądamy blokady FOR UPDATE na czas transakcji. Inny przelew poczeka na te wiersze. order_by(ID) narzuca zgodną kolejność blokowania, zmniejszając ryzyko zakleszczeń.', 'Select both accounts and request FOR UPDATE row locks for the transaction. Another transfer waits for these rows. Ordering by ID establishes consistent lock order, reducing deadlock risk.')
note('accounts = (await session.execute(statement)).scalars().all()', 'Wykonujemy zapytanie blokujące wiersze kont. Po await wyciągamy obiekty Account do listy. Jeśli inna transakcja trzyma blokadę, oczekiwanie nie blokuje całej pętli zdarzeń.', 'Execute the query locking the account rows. After await, extract Account objects into a list. Waiting for another transaction’s row lock does not block the entire event loop.')
note('accounts = (await session.execute(select(Account).order_by(Account.id))).scalars().all()', 'Odczytujemy konta po zatwierdzonym przelewie albo rollbacku. scalars().all() daje listę Account uporządkowaną według ID; ten odczyt sprawdza rzeczywisty stan bazy.', 'Read accounts after a committed transfer or rollback. scalars().all() returns Account objects ordered by ID; this checks actual database state.')
note('session.add_all([Account(id=1, balance=1000), Account(id=2, balance=500)])', 'Przygotowujemy dwa konta: 1 → 1000 i 2 → 500 groszy. add_all rejestruje listę nowych obiektów bez await. Wyjście z factory.begin zapisze oba.', 'Prepare two accounts: 1 → 1000 and 2 → 500 cents. add_all registers new objects without await. Exiting factory.begin saves both.')
note('session.add(Transfer(description=f"Transfer {data[\'amount\']} cents"))', 'Dodajemy wpis historii przelewu w tej samej transakcji co salda. Jeśli zapis historii zawiedzie, zmiany sald również zostaną wycofane.', 'Add a transfer history record in the same transaction as the balances. If saving the history fails, balance changes are rolled back too.')
note('if data["amount"] == 13:', 'To jawnie edukacyjny punkt awarii: kwota 13 wywoła błąd po odjęciu i flush, ale przed dodaniem odbiorcy. Pozwala sprawdzić prawdziwy rollback zapisu. Taka specjalna kwota nie należy do reguł zwykłej aplikacji.', 'This explicit teaching fault triggers for amount 13 after debit and flush, but before credit. It demonstrates a real write rollback. This special amount is not a normal application rule.')
note('data = await response.json()', 'Odczytujemy body odpowiedzi serwera i dekodujemy JSON do słownika. To odpowiedź zewnętrznego API, nie JSON przychodzącego requestu naszego serwera.', 'Read the server response body and decode JSON into a dictionary. This is an external API response, not an incoming request to our server.')
note('return await response.json()', 'Czekamy na body zewnętrznej odpowiedzi, zamieniamy JSON na obiekt Pythona i zwracamy go z fetch. gather zbierze te zwrócone obiekty.', 'Await the external response body, decode its JSON into a Python object, and return it from fetch. gather collects these returned objects.')
note('response.raise_for_status()', 'Sprawdzamy odebrany status. Dla 4xx/5xx zgłaszany jest wyjątek zamiast próby odczytania błędu jako poprawnej ceny. Ta metoda nie potrzebuje await.', 'Check the received status. 4xx/5xx raises an exception rather than treating an error body as a valid price. This method needs no await.')
note('results = await asyncio.gather(operation("A", 1), operation("B", 4), operation("C", 2))', 'Tworzymy trzy korutyny i przekazujemy je gather. Oczekiwania 1, 4 i 2 sekundy nakładają się, więc całość trwa około 4 s. results ma kolejność wejściową [1, 4, 2], chociaż kolejność końców to A, C, B.', 'Create three coroutines and pass them to gather. Their waits of 1, 4 and 2 seconds overlap, so total duration is about 4 s. results preserves input order [1, 4, 2], although completion order is A, C, B.')
note('results = await asyncio.gather(*(fetch(session, url) for url in urls))', 'Generator tworzy fetch dla każdego URL, a * przekazuje je jako oddzielne argumenty gather. Jedna sesja HTTP obsługuje trzy współbieżne odczyty. Lista results zachowuje kolejność urls. Sesji HTTP można używać współbieżnie; AsyncSession bazy nie należy tak współdzielić.', 'The generator creates fetch for each URL; * passes them as separate gather arguments. One HTTP session handles three concurrent reads. results preserves urls order. An HTTP session can be shared this way; a database AsyncSession must not be shared between concurrent tasks.')
note('await asyncio.sleep(0.1)', 'Oddajemy pętli sterowanie na około 0,1 s, aby zaplanowane żądanie czatu mogło ruszyć. Potem wyślemy szybkie żądanie statusu, zanim czat skończy trzysekundowe oczekiwanie.', 'Yield for about 0.1 s so the scheduled chat request can start. Then send a fast status request before the chat finishes its three-second wait.')
note('await asyncio.sleep(3)', 'Symulujemy trzysekundowe oczekiwanie na usługę AI. Korutyna czatu zostaje zawieszona, a event loop może obsłużyć /api/status. Nie uruchamiamy tu prawdziwego modelu AI.', 'Simulate a three-second wait for an AI service. The chat coroutine suspends while the event loop can serve /api/status. No real AI model runs here.')
note('await asyncio.sleep(delay)', 'Zawieszamy bieżącą korutynę na delay sekund. W tym czasie inne gotowe korutyny mogą działać. To symulacja oczekiwania I/O, nie pomiar intensywnych obliczeń.', 'Suspend this coroutine for delay seconds. Other ready coroutines may run meanwhile. This simulates I/O waiting rather than intensive computation.')
note('chat_task = asyncio.create_task(request(client, "POST", url + "/api/v1/chat", {"prompt": "Explain await"}))', 'Tworzymy Task dla żądania POST z promptem Explain await. create_task planuje korutynę, lecz nie czeka na odpowiedź. Zachowujemy uchwyt chat_task, aby później odebrać wynik i ewentualny wyjątek.', 'Create a Task for the POST request with prompt Explain await. create_task schedules it without waiting for a response. Keep chat_task to retrieve its result or exception later.')
note('await request(client, "GET", url + "/api/status")', 'Wysyłamy drugie żądanie tym samym klientem, gdy czat nadal czeka. Status OK powinien pojawić się w dzienniku przed odpowiedzią czatu: to dowód, że sleep w handlerze oddaje sterowanie.', 'Send a second request using the same client while chat is waiting. Status OK should appear in the log before the chat response, demonstrating that the handler sleep yields control.')
note('await chat_task', 'Czekamy na zakończenie wcześniej utworzonego Task czatu. Nie uruchamiamy drugiego czatu. Ewentualny wyjątek zostanie zgłoszony tutaj, zamiast pozostać nieodebrany.', 'Wait for the previously created chat Task. This does not start another chat. Any exception is retrieved here instead of remaining unobserved.')
note('async with session.get(url) as response:', 'Wysyłamy asynchroniczne GET na url. Po otrzymaniu nagłówków response opisuje odpowiedź; body przeczytamy osobno. async with zwolni odpowiedź i umożliwi ponowne użycie połączenia.', 'Send an async GET to url. After headers arrive response describes the reply; the body is read separately. async with releases the response and permits connection reuse.')
note('async with ClientSession(timeout=ClientTimeout(total=15)) as session:', 'Tworzymy klienta HTTP z pulą połączeń i limitem 15 s na żądanie. async with zamknie sesję także przy błędzie. To ClientSession sieci, a nie AsyncSession SQLAlchemy.', 'Create an HTTP client with a connection pool and a 15-second total request timeout. async with closes it even on error. This is a network ClientSession, not a SQLAlchemy AsyncSession.')
note('async with ClientSession() as client:', 'Tworzymy jednego klienta HTTP do lokalnych żądań. Sesja współdzieli pulę połączeń; blok async with zamknie ją po zakończeniu pokazu.', 'Create one HTTP client for local requests. Its session shares a connection pool; async with closes it when the demo finishes.')
note('async with server(app) as url:', 'Pomocnik uruchamia prawdziwy serwer aiohttp na wolnym porcie localhost. url zawiera jego adres. Po wyjściu z bloku runner.cleanup zatrzyma serwer i posprząta zasoby.', 'The helper starts a real aiohttp server on an available localhost port. url holds its address. On exiting, runner.cleanup stops the server and cleans up resources.')
note('if __name__ == "__main__":', 'Ten warunek jest prawdziwy przy uruchomieniu pliku jako skryptu. Import pliku nie uruchomi pokazu. Stąd przechodzimy do launch, asyncio.run i main.', 'This condition is true when executing the file as a script. Importing it does not launch the demo. Execution goes from here to launch, asyncio.run and main.')
note('launch(lambda options: asyncio.run(main()))', 'launch dodaje zdarzenia START/END i pomiar czasu. lambda jest funkcją przekazaną do launch; options to dane wariantu, tutaj nieużywane. main() tworzy korutynę, a asyncio.run uruchamia ją w nowej pętli i zamyka pętlę po zakończeniu.', 'launch adds START/END events and timing. lambda is the function passed to launch; options are unused preset data here. main() creates a coroutine; asyncio.run executes it in a new loop and closes the loop afterwards.')
note('setup_routes(app, create_product, list_products, get_product)', 'Przekazujemy aplikację i trzy funkcje do routes.py. setup_routes rejestruje adresy, ale nie wywołuje handlerów. Przekazanie funkcji jawnie zapobiega cyklicznemu importowi task19 ↔ routes.', 'Pass the application and three functions to routes.py. setup_routes registers URLs without calling the handlers. Explicit handler arguments avoid a circular import between task19 and routes.')


FUNCTIONS = {
    'main': ('Główna korutyna przygotowuje dane i uruchamia pokaz. Definicja nie wykonuje ciała; wykonanie zacznie się przez asyncio.run(main()).', 'The main coroutine prepares data and runs the demo. Defining it does not run its body; asyncio.run(main()) starts execution.'),
    'hello': ('Handler powitania otrzyma request od aiohttp dopiero po dopasowaniu trasy. Jego return stanie się odpowiedzią HTTP.', 'The greeting handler receives request from aiohttp after route matching. Its return becomes the HTTP response.'),
    'create_product': ('Handler POST odbierze JSON, zwaliduje go, zapisze produkt w transakcji i zwróci JSON ze statusem 201.', 'The POST handler reads and validates JSON, saves a product in a transaction and returns JSON with status 201.'),
    'list_products': ('Handler GET pobierze produkty. request daje dostęp do fabryki sesji i parametrów query. Wyniki przekształcimy na listę JSON.', 'The GET handler retrieves products. request provides the session factory and query parameters. Results become a JSON list.'),
    'get_product': ('Handler otrzyma ID z URL i pobierze produkt. Brak rekordu zostanie zamieniony na odpowiedź 404, zamiast błędu atrybutu None.', 'The handler reads an ID from the URL and retrieves a product. An absent row becomes 404 instead of an attribute error on None.'),
    'update_product': ('Handler PATCH zmieni tylko przesłane pola. Odczyt i zapis należą do jednej transakcji.', 'The PATCH handler changes only submitted fields. Read and write belong to one transaction.'),
    'delete_product': ('Handler DELETE usunie wskazany produkt. Po zatwierdzeniu zwróci 204 z pustym body.', 'The DELETE handler removes the requested product. After commit it returns 204 with an empty body.'),
    'echo': ('Handler odczyta body JSON i odeśle tę samą strukturę jako JSON. To nie jest drukowanie do terminala.', 'The handler reads a JSON body and returns the same structure as JSON. This is not terminal printing.'),
    'search': ('Handler wyszukiwania odczyta q z query string, np. /api/search?q=python. Brak parametru obsłuży osobną gałęzią.', 'The search handler reads q from a query string such as /api/search?q=python. A separate branch handles its absence.'),
    'status': ('Szybki handler stanu zwraca JSON. Nie ma powodu dodawać await do samego tworzenia odpowiedzi.', 'The fast status handler returns JSON. Creating a response alone does not require await.'),
    'transfer': ('Handler przelewu waliduje wejście i zmienia dwa salda atomowo. Blokady wierszy chronią odczyt sald przed równoczesnymi przelewami.', 'The transfer handler validates input and updates two balances atomically. Row locks protect balance reads from concurrent transfers.'),
    'balances': ('Handler kontrolny odczyta salda bez ich zmieniania. Użyjemy go przed i po błędzie, aby potwierdzić rollback.', 'This inspection handler reads balances without changing them. It verifies rollback by comparing state around a failure.'),
    'fetch': ('Korutyna klienta otrzymuje wspólną sesję HTTP oraz URL. Zwróci zdekodowany JSON; sama nie tworzy osobnej sesji.', 'The client coroutine receives a shared HTTP session and a URL. It returns decoded JSON without creating another session.'),
    'operation': ('Korutyna otrzyma nazwę i opóźnienie, zaczeka bez blokowania pętli, a następnie zwróci delay.', 'The coroutine receives a name and delay, waits without blocking the loop, then returns delay.'),
    'chat': ('Handler udaje usługę AI: odbierze prompt i poczeka 3 sekundy. W czasie czekania inne żądania mogą być obsługiwane.', 'The handler simulates an AI service by reading a prompt and waiting three seconds. Other requests can be served during the wait.'),
}


def explain(line):
    s = line.strip()
    if s in EXACT:
        return EXACT[s]
    if s.startswith(('import ', 'from ')):
        if s.startswith('import '):
            name = s[7:]
        else:
            name = s.split(' import ')[0][5:]
        meanings = {
            'asyncio': ('pętlą zdarzeń, korutynami, sleep i gather', 'the event loop, coroutines, sleep and gather'),
            'aiohttp': ('asynchronicznym HTTP: web buduje serwer, ClientSession wysyła żądania', 'async HTTP: web builds servers, ClientSession sends requests'),
            'lab_support': ('zdarzeniami i pomiarem czasu pokazu, niezależnymi od logiki API', 'demo events and timing, separate from API logic'),
            'api_support': ('lokalnym serwerem testowym, walidacją i izolowaną bazą; pełny kod jest w osobnym pliku', 'local test servers, validation and isolated database setup; the full code is in a separate file'),
            'sqlalchemy': ('typami kolumn i budowaniem zapytań SQL', 'column types and SQL query construction'),
            'sqlalchemy.orm': ('bazą modeli, adnotacjami Mapped i definicjami kolumn mapped_column', 'model bases, Mapped annotations and mapped_column definitions'),
            'datetime': ('odczytem daty i czasu', 'date and time retrieval'),
            'json': ('dekodowaniem JSON i rozpoznawaniem JSONDecodeError', 'JSON decoding and JSONDecodeError'),
            'routes': ('funkcją rejestrującą trasy zadania 19', 'the function registering task 19 routes'),
        }
        pl,en = meanings[name]
        return pair(f'Import z {name} udostępnia narzędzia związane z {pl}. Import nie uruchamia main ani nie wysyła żądania.', f'Import from {name} provides tools for {en}. Importing does not run main or send a request.')
    if s.startswith('async def '):
        name = s[10:].split('(')[0]
        return pair(*FUNCTIONS[name])
    if s == 'def to_dict(self):':
        return pair('Zwykła metoda modelu, bez async: zamieni już dostępne atrybuty self na słownik. Nie wykonuje zapytania SQL.', 'An ordinary model method, without async: it converts already available self attributes into a dictionary. It performs no SQL query.')
    if s.startswith('class '):
        name=s.split()[1].split('(')[0]
        return pair('Definiujemy klasę '+name+('. Dziedziczenie po DeclarativeBase tworzy rejestr modeli i metadata. To nie tabela biznesowa.' if name=='Base' else '. Dziedziczy po Base, więc SQLAlchemy zarejestruje jej tabelę. Sama definicja klasy jeszcze nie tworzy tabeli w PostgreSQL.'), 'Define class '+name+('. DeclarativeBase supplies the model registry and metadata. It is not a business table.' if name=='Base' else '. Inheriting Base registers its table with SQLAlchemy. Defining the class does not yet create the PostgreSQL table.'))
    if s == 'pass':
        return pair('Pusta instrukcja w ciele Base. Nie potrzebujemy dodatkowych metod; zachowanie dostajemy przez dziedziczenie.', 'An empty statement in Base. No additional methods are needed; behavior is inherited.')
    if s.startswith('__tablename__'):
        name=s.split('=')[1].strip()
        return pair(f'Określamy nazwę tabeli SQL jako {name}. To nazwa w bazie, która może różnić się od nazwy klasy Pythona.', f'Set the SQL table name to {name}. The database name can differ from the Python class name.')
    if 'mapped_column(' in s:
        field=s.split(':')[0]
        if 'primary_key' in s:
            pl,en='Klucz główny jednoznacznie identyfikuje rekord; PostgreSQL wygeneruje ID podczas INSERT.', 'The primary key uniquely identifies a row; PostgreSQL generates its ID during INSERT.'
        elif 'ForeignKey' in s:
            pl,en='ForeignKey("users.id") łączy produkt z istniejącym użytkownikiem i pozwala JOIN ustalić warunek połączenia.', 'ForeignKey("users.id") links the product to an existing user and lets JOIN infer its condition.'
        elif 'String' in s:
            size=s.split('String(')[1].split(')')[0]
            pl,en=f'String({size}) ogranicza tekst do {size} znaków.', f'String({size}) limits text to {size} characters.'
        else:
            pl,en='Integer przechowuje liczbę całkowitą; ceny i salda wyrażamy w groszach, żeby uniknąć błędów float.', 'Integer stores a whole number; prices and balances use cents to avoid float rounding errors.'
        return pair(f'Pole {field}: Mapped opisuje typ atrybutu ORM, mapped_column definiuje kolumnę SQL. {pl}', f'Field {field}: Mapped describes the ORM attribute type; mapped_column defines its SQL column. {en}')
    if s.startswith('app.router.add_'):
        tree=ast.parse(s).body[0].value
        method=tree.func.attr[4:].upper(); path=ast.literal_eval(tree.args[0]); handler=ast.unparse(tree.args[1])
        return pair(f'Rejestrujemy {method} {path} → {handler}. Przekazujemy funkcję bez (), więc nie wywołujemy jej teraz. aiohttp zrobi to po dopasowaniu metody i ścieżki żądania.', f'Register {method} {path} → {handler}. Pass the function without (), so it is not called now. aiohttp calls it after matching request method and path.')
    if s.startswith('await demo(app,'):
        return pair('Uruchamiamy pomocnika pokazu: startuje prawdziwy serwer na wolnym porcie, klient wysyła wymienione żądania po kolei i porównuje statusy z oczekiwaniami. Każda krotka to (metoda, ścieżka, JSON, oczekiwany status). Dziennik pokazuje również body. Po pokazie serwer jest zamykany.', 'Run the demo helper: it starts a real server on an available port, sends listed requests sequentially and checks expected statuses. Each tuple is (method, path, JSON, expected status). The log includes response bodies. The server closes after the demo.')
    if s.startswith(('("POST",', '("GET",', "('POST',", "('GET',", "('PATCH',", "('DELETE',")):
        method,path,data,status=ast.literal_eval(s.rstrip(','))
        return pair(f'Przypadek pokazu: {method} {path}. Body: {data!r}; None oznacza brak danych. Oczekujemy statusu {status}. Pomocnik wyśle to żądanie po zakończeniu poprzedniego i zapisze body odpowiedzi. Porównaj wartości z wcześniejszym stanem bazy.', f'Demo case: {method} {path}. Body: {data!r}; None means no data. Expect status {status}. The helper sends this request after the previous one completes and logs the response body. Compare values with the previous database state.')
    if s == '])':
        return pair('Zamykamy listę przypadków ] i wywołanie demo ). To kontynuacja poprzedniej instrukcji, a nie osobne działanie. await zaczeka na cały pokaz.', 'Close the case list ] and demo call ). This continues the previous statement rather than performing a separate operation. await waits for the whole demo.')
    if s.startswith('with span('):
        return pair('Pomocnik obserwacji zapisuje początek i koniec tego bloku z czasem. Nawet przy wyjątku finally w span zapisze koniec. Pasek obejmuje czekanie; nie mierzy pracy procesora.', 'The observation helper records this block’s start and end timestamps. Its finally records the end even on an exception. The bar includes waiting and does not measure CPU work.')
    if s.startswith('metric('):
        return pair('Publikujemy wskazaną wartość w panelu wyników i terminalu jako zdarzenie JSON. Argument pierwszy jest etykietą, drugi wynikiem. Nie zmieniamy danych w bazie; str zamienia listę na czytelny tekst, a data["data"]["amount"] odczytuje cenę z zagnieżdżonego JSON.', 'Publish the specified value in the results panel and terminal as a JSON event. The first argument is the label; the second is the value. This does not modify the database. str turns a list into text; data["data"]["amount"] reads a price from nested JSON.')
    if s.startswith('event('):
        return pair('Rejestrujemy w dzienniku zakończenie transakcji. Wcięcie jest już poza session.begin, dlatego COMMIT nastąpił przed tym komunikatem. To obserwacja, a nie instrukcja wykonująca commit.', 'Record transaction completion in the log. Indentation is outside session.begin, so COMMIT already happened. This observes commit rather than performing it.')
    if s.startswith('raise web.'):
        error=s.split('web.')[1].split('(')[0]
        statuses={'HTTPBadRequest':400,'HTTPNotFound':404,'HTTPForbidden':403,'HTTPConflict':409}
        return pair(f'Przerywamy handler wyjątkiem {error}. aiohttp zamieni go na odpowiedź HTTP {statuses[error]} z podanym tekstem. Jeśli wyjątek wychodzi z session.begin, zmiany tej transakcji zostaną wycofane. Dalsze linie handlera nie wykonają się.', f'Interrupt the handler with {error}. aiohttp converts it into HTTP {statuses[error]} with the given text. If it escapes session.begin, that transaction rolls back. The remaining handler lines do not run.')
    if s.startswith('return web.json_response('):
        value=s[len('return web.json_response('):-1]
        return pair(f'Zwracamy odpowiedź JSON z wyrażenia {value}. json_response koduje wartości Pythona i ustawia Content-Type: application/json. Domyślny status to 200; status=201 oznacza utworzenie, a 400 błędne wejście. return kończy handler i oddaje odpowiedź aiohttp.', f'Return a JSON response from {value}. json_response encodes Python values and sets Content-Type: application/json. Default status is 200; status=201 means creation and 400 means invalid input. return ends the handler and hands the response to aiohttp.')
    if s.startswith('return web.Response('):
        if '204' in s:
            return pair('Zwracamy 204 No Content po usunięciu. Odpowiedź ma puste body, więc klient nie powinien próbować odczytywać z niej JSON.', 'Return 204 No Content after deletion. Its body is empty, so a client should not attempt JSON decoding.')
        if 'text/html' in s:
            return pair('Tworzymy odpowiedź z treścią HTML i typem text/html. Przeglądarka zinterpretuje <h1> jako nagłówek. return kończy handler. W tym przykładzie HTML jest stałym tekstem.', 'Create a response with HTML content and text/html type. Browsers render <h1> as a heading. return ends the handler. This example uses constant HTML.')
        return pair('f-string wstawia name do powitania, np. Hello, Anna!. Zwracamy zwykły tekst (domyślnie text/plain), dzięki czemu nazwa użytkownika nie jest interpretowana jako HTML.', 'The f-string inserts name into the greeting, such as Hello, Anna!. Return plain text (text/plain by default), so user input is not interpreted as HTML.')
    if s.startswith('if '):
        condition=s[3:-1]
        notes={
            'product is None':('None oznacza brak produktu. Tylko wtedy wejdziemy do gałęzi 404.', 'None means no product. Only then do we enter the 404 branch.'),
            'row is None':('JOIN nie znalazł pasującego rekordu. Zwrócimy 404 przed rozpakowaniem wiersza.', 'JOIN found no matching row. Return 404 before unpacking.'),
            'query is None':('Sprawdzamy brak q, nie pusty napis. ?q= i brak q to różne wejścia.', 'Check absent q rather than an empty string. ?q= and no q are different inputs.'),
            'name == "admin"':('Porównanie jest czułe na wielkość liter. Tylko dokładne admin otrzyma 403.', 'Comparison is case-sensitive. Only exact admin receives 403.'),
            '"name" in data':('Sprawdzamy obecność klucza name; nieobecna nazwa pozostanie bez zmian.', 'Check whether the name key exists; an absent name remains unchanged.'),
            '"price" in data':('Sprawdzamy obecność klucza, więc również price=0 zostanie poprawnie zaktualizowane.', 'Check key presence, so price=0 is correctly updated too.'),
            'len(by_id) != 2':('Potrzebujemy dokładnie dwóch istniejących kont; brak któregokolwiek to 404.', 'Exactly two existing accounts are required; either missing account means 404.'),
            'source.balance < data["amount"]':('Kwota większa od dostępnego salda zostanie odrzucona przed zmianą sald.', 'An amount exceeding available balance is rejected before balance changes.'),
            'data["from_id"] == data["to_id"]':('Przelew na to samo konto nie ma sensu w tym ćwiczeniu, więc odrzucamy go statusem 400.', 'A self-transfer is rejected with 400 in this exercise.'),
            'limit > 100':('Ograniczamy wielkość jednej strony do 100, aby klient nie pobierał nieograniczonej listy.', 'Bound a page to 100 items so clients cannot request an unbounded list.'),
            'not isinstance(prompt, str) or not prompt.strip()':('Akceptujemy wyłącznie tekst z co najmniej jednym znakiem innym niż biały. or odrzuca błędny typ przed próbą strip.', 'Accept only text containing a non-whitespace character. or rejects the wrong type before calling strip.'),
            'set(data) != {"from_id", "to_id", "amount"}':('Porównujemy zestaw kluczy JSON z trzema wymaganymi polami; brakujące i dodatkowe klucze są błędem.', 'Compare JSON keys with the three required fields; missing and extra keys are errors.'),
            'any(type(data[key]) is not int or not 1 <= data[key] <= 2147483647 for key in data)':('any sprawdza wszystkie wartości wejścia: dodatnie int w zakresie PostgreSQL Integer. type(... ) is int odrzuca także bool, mimo że bool dziedziczy po int.', 'any checks all input values: positive ints within PostgreSQL Integer bounds. type(...) is int also rejects bool, despite bool inheriting int.'),
        }
        return pair(*notes[condition])
    if s == 'try:':
        return pair('Początek bloku obsługi błędu JSON. Jeśli parsowanie zawiedzie, wykonanie przejdzie do pasującego except; prawidłowe dane przejdą dalej.', 'Start the JSON error-handling block. Parsing failure transfers control to the matching except; valid data continues normally.')
    if s.startswith('except '):
        return pair('Przechwytujemy wyłącznie błędy dekodowania JSON i kodowania znaków. Zamienimy je na 400. Inne błędy programowania nie zostają ukryte szerokim except Exception.', 'Catch only JSON decoding and character decoding errors and convert them to 400. Other programming errors are not hidden by a broad except Exception.')
    if s.startswith(('page =', 'limit =')):
        field=s.split(' =')[0]; default='1' if field=='page' else '10'
        return pair(f'Odczytujemy {field} z query jako tekst; przy braku używamy {default}. positive_id zamienia go na dodatni int. Zero, liczby ujemne i nieliczbowe wartości dają 400.', f'Read {field} from query as text, defaulting to {default}. positive_id converts it to a positive int. Zero, negatives and nonnumeric values return 400.')
    if s.startswith('url ='):
        return pair('Zapisujemy adres publicznego endpointu ceny BTC w USD. Zastępuje wskazany w poleceniu stary CoinDesk. Ten pokaz potrzebuje internetu; otrzymana cena jest bieżąca, a nie stałą daną ćwiczenia.', 'Store the public BTC/USD price endpoint URL, replacing the old CoinDesk URL from the assignment. This demo requires internet; its price is live rather than fixed exercise data.')
    if s.startswith('urls ='):
        return pair('Lista składana tworzy trzy różne adresy dla BTC, ETH i LTC. f-string podstawia symbol do URL. Samo tworzenie listy nie wysyła żadnego żądania HTTP.', 'The list comprehension creates three different URLs for BTC, ETH and LTC. The f-string inserts each symbol. Constructing the list sends no HTTP requests.')
    if s == 'for data in results:':
        return pair('Iterujemy po odpowiedziach z gather w kolejności wejściowych URL. data w każdej iteracji to jeden słownik odpowiedzi z ceną danej waluty.', 'Iterate over gather responses in input URL order. In each iteration data is one response dictionary containing that currency’s price.')
    if s == 'prompt = data.get("prompt")':
        return pair('Ze słownika JSON odczytujemy prompt. Przy braku klucza get zwraca None; następny warunek sprawdzi typ i niepustą treść.', 'Read prompt from the JSON dictionary. Missing keys return None; the next condition checks type and nonempty content.')
    if s == 'return delay':
        return pair('Kończymy operation i przekazujemy liczbę sekund do gather. Ta wartość trafi na odpowiednią pozycję listy results.', 'End operation and return the delay to gather. This value occupies its input-order position in results.')
    raise ValueError('Missing reviewed explanation: ' + s)
